// Author: abhinavkumarrath #include <bits/stdc++.h>using namespace std; #pragma GCC optimize("O3,unroll-loops")#pragma GCC target("avx2,bmi,bmi2,lzcnt,popcnt") using ll = long long;using vi = vector<int>;using vll = vector<ll>;using pii = pair<int, int>; #define pb push_back#define all(x) (x).begin(), (x).end()#define sz(x) (int)(x).size()#define fi first#define se second#define rep(i, a, b) for (int i = (a); i < (b); ++i)#define forn(i, n) rep(i, 0, n)#define per(i, a, b) for (int i = (b) - 1; i >= (a); --i)#define rofn(i, n) per(i, 0, n) template<class T> bool chmin(T& a, const T& b) { if (b < a) { a = b; return 1; } return 0; }template<class T> bool chmax(T& a, const T& b) { if (a < b) { a = b; return 1; } return 0; } void yes() { cout << "YES\n"; }void no() { cout << "NO\n"; } const int INF = 1e9;const ll LINF = 1e18; void solve() {    int n;    if (!(cin >> n)) return;        vector<string> s(n);    forn(i, n) cin >> s[i];        string colors = "RGBYW";    int ans = 10;        forn(mask, 1024) {        bool ok = true;                forn(i, n) {            rep(j, i + 1, n) {                if (s[i] == s[j]) continue;                                int c1 = colors.find(s[i][0]);                int v1 = s[i][1] - '1';                int c2 = colors.find(s[j][0]);                int v2 = s[j][1] - '1';                                bool color_fail = (c1 == c2) || (!(mask & (1 << c1)) && !(mask & (1 << c2)));                bool value_fail = (v1 == v2) || (!(mask & (1 << (v1 + 5))) && !(mask & (1 << (v2 + 5))));                                if (color_fail && value_fail) {                    ok = false;                    break;                }            }            if (!ok) break;        }                if (ok) {            chmin(ans, __builtin_popcount(mask));        }    }        cout << ans << "\n";} int main() {    ios_base::sync_with_stdio(false);    cin.tie(nullptr);        int t = 1;    while (t--) {        solve();    }        return 0;}